<template><main class="paper-shell"><div class="paper-container admin-container"><header class="paper-workspace-header"><div><div class="paper-page-eyebrow">Knowledge Base / Administration</div><h1 class="paper-page-title">Processing jobs</h1><p class="paper-page-description">Inspect, filter, retry, and archive collection, parsing, and extraction jobs.</p></div><button class="paper-button" @click="load">Refresh</button></header><LiteratureAdminNav/><p v-if="message" class="admin-notice" :class="{error}">{{message}}</p><section class="summary-grid"><article v-for="([key,value]) in Object.entries(stats).slice(0,8)" :key="key"><strong>{{value}}</strong><span>{{humanize(key)}}</span></article></section><section class="paper-panel admin-card"><form class="job-filters" @submit.prevent="load"><label>Stage<select v-model="filters.stage"><option value="">All stages</option><option value="parse">Parse</option><option value="extract">Extract</option></select></label><label>Status<select v-model="filters.status"><option value="">All statuses</option><option value="pending">Pending</option><option value="running">Running</option><option value="done">Done</option><option value="failed">Failed</option><option value="permanent_failed">Permanent failure</option></select></label><label>Error class<input v-model="filters.error_class" placeholder="Optional error category"/></label><button class="admin-action">Apply filters</button></form><div v-if="loading" class="empty">Loading jobs…</div><div v-else-if="!jobs.length" class="empty">No matching jobs.</div><div v-else class="table-wrap"><table><thead><tr><th>ID</th><th>Stage</th><th>Paper</th><th>Status</th><th>Created</th><th>Error / result</th><th>Action</th></tr></thead><tbody><tr v-for="job in jobs" :key="job.id"><td>{{job.id}}</td><td>{{job.stage||job.job_type}}</td><td><NuxtLink v-if="job.paper_id" :to="`/literature/${job.paper_id}`">{{job.paper_id}}</NuxtLink><span v-else>—</span></td><td>{{job.status}}</td><td>{{format(job.created_at||job.started_at)}}</td><td>{{job.error_msg||job.message||'—'}}</td><td><button v-if="['failed','permanent_failed'].includes(String(job.status).toLowerCase())&&job.paper_id" :disabled="busy===job.id" @click="retry(job)">Retry</button></td></tr></tbody></table></div><div class="archive"><label>Archive completed jobs older than <input v-model.number="archiveDays" type="number" min="1"/> days</label><button class="admin-action" @click="archive">Archive</button></div></section></div></main></template>
<script setup>
import '~/assets/paper-platform.css';import {authState,loadCurrentUser} from '~/utils/auth';definePageMeta({middleware:'auth-client'});useHead({title:'Literature Jobs - OpenIsle'});const api=useLiteratureAdmin(),jobs=ref([]),stats=ref({}),filters=reactive({stage:'',status:'',error_class:''}),loading=ref(true),busy=ref(null),archiveDays=ref(7),message=ref(''),error=ref(false);const ensure=async()=>{if(!authState.role)await loadCurrentUser();if(authState.role!=='ADMIN')return navigateTo('/literature/workflow');return true};const load=async()=>{loading.value=true;try{if(!await ensure())return;const params={limit:100,...Object.fromEntries(Object.entries(filters).filter(([,v])=>v))};const [list,summary]=await Promise.all([api.get('/jobs',params),api.get('/jobs/stats')]);jobs.value=list.jobs||list.items||list||[];stats.value=summary}catch(e){error.value=true;message.value=e?.data?.message||e.message}finally{loading.value=false}};const retry=async job=>{busy.value=job.id;try{await api.post('/retry',{paper_id:job.paper_id,stage:job.stage||job.job_type,job_id:job.id});message.value='Retry task submitted.';await load()}catch(e){error.value=true;message.value=e?.data?.message||e.message}finally{busy.value=null}};const archive=async()=>{try{await api.post('/jobs/archive',{days:archiveDays.value,batch:1000});message.value='Archive task submitted.';await load()}catch(e){error.value=true;message.value=e?.data?.message||e.message}};const humanize=v=>v.replaceAll('_',' ');const format=v=>v?new Date(v).toLocaleString():'—';onMounted(load)
</script><style scoped src="~/assets/literature-admin.css"></style><style scoped>.job-filters{display:flex;align-items:end;gap:12px;margin-bottom:18px}.job-filters label{display:grid;gap:5px;color:var(--paper-muted);font-size:12px;font-weight:750}.job-filters input,.job-filters select,.archive input{min-height:38px;border:1px solid var(--paper-line);padding:8px;background:#fff}.archive{display:flex;align-items:end;justify-content:flex-end;gap:10px;margin-top:16px}.archive label{color:var(--paper-muted);font-size:12px}@media(max-width:700px){.job-filters{align-items:stretch;flex-direction:column}}</style>
